public readonly record struct AuthStamp(long UserId, int SchoolId);

public sealed class AttemptContext
{
    public AuthStamp Stamp { get; init; }
}

public AuthStamp OnStack(long userId, int schoolId) => new(userId, schoolId);

public object Boxed(AuthStamp stamp) => stamp;

public async Task<AuthStamp> AcrossAwaitAsync(AuthStamp stamp, CancellationToken cancellationToken)
{
    await Task.Yield();
    cancellationToken.ThrowIfCancellationRequested();
    return stamp;
}
